using Swashbuckle.AspNetCore.Annotations;namespace GraphApi.Models.USR.Modelos{    [SwaggerSchema("Modelo de lectura de un Modelo")]    [GraphQLDescription("Objeto que representa un Modelo existente.")]    public class clReadModelos    {        [SwaggerSchema("Identificador único del Modelo")]        [GraphQLDescription("Identificador único del Modelo")]        public int? ModeloID { get; set; }        [SwaggerSchema("MarcaID")]        [GraphQLDescription("MarcaID")]        public int? MarcaID { get; set; }        [SwaggerSchema("Modelo")]        [GraphQLDescription("Modelo")]        public string? Modelo { get; set; } = default!;        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }    [SwaggerSchema("Modelo de creación de un Modelo")]    [GraphQLDescription("Input para crear un Modelo.")]    public class clCreateModelos    {        [GraphQLNonNullType] [SwaggerSchema("MarcaID")]        [GraphQLDescription("MarcaID")]        public int MarcaID { get; set; }        [GraphQLNonNullType] [SwaggerSchema("Modelo")]        [GraphQLDescription("Modelo")]        public string Modelo { get; set; } = default!;        [GraphQLNonNullType] [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool bEliminado { get; set; }    }    [SwaggerSchema("Modelo de actualización de un Modelo")]    [GraphQLDescription("Input para actualizar parcialmente un Modelo.")]    public class clUpdateModelos    {        [SwaggerSchema("Identificador único del Modelo")]        [GraphQLDescription("Identificador único del Modelo")]        public int? ModeloID { get; set; }        [SwaggerSchema("MarcaID")]        [GraphQLDescription("MarcaID")]        public int? MarcaID { get; set; }        [SwaggerSchema("Modelo")]        [GraphQLDescription("Modelo")]        public string? Modelo { get; set; }        [SwaggerSchema("bEliminado")]        [GraphQLDescription("bEliminado")]        public bool? bEliminado { get; set; }    }}